import { Component, OnInit } from "@angular/core";
import * as jQuery from "jquery";
import { Router } from "@angular/router";

@Component({
  selector: "app-home",
  templateUrl: "./home.component.html",
  styleUrls: ["./home.component.css"],
})
export class HomeComponent implements OnInit {
  private unidades_selecionadas = [null];
  private unidades_selecionadas_object = [null];
  private unidade_padrao = 0;

  constructor(private router: Router) {
    if (
      localStorage.getItem("totem.credenciais") == "" ||
      localStorage.getItem("totem.credenciais") === null
    )
      localStorage.setItem("totem.credenciais", "{}");
    if (
      localStorage.getItem("totem.servidor") == "" ||
      localStorage.getItem("totem.servidor") === null
    )
      localStorage.setItem("totem.servidor", "{}");
    if (
      localStorage.getItem("totem.servicos") == "" ||
      localStorage.getItem("totem.servicos") === null
    )
      localStorage.setItem("totem.servicos", "[]");
    if (
      localStorage.getItem("totem.servicos_selecionados") == "" ||
      localStorage.getItem("totem.servicos_selecionados") === null
    )
      localStorage.setItem("totem.servicos_selecionados", "[]");

    setTimeout(() => {
      if (
        localStorage.getItem("totem.unidades_completo") == null ||
        localStorage.getItem("totem.unidades_completo") == "[]" ||
        localStorage.getItem("totem.unidades_completo") == ""
      ) {
        localStorage.setItem("totem.unidades_completo", "[]");
        this.router.navigateByUrl("/configuracao");
      } else {
        this.unidades_selecionadas_object = JSON.parse(
          localStorage.getItem("totem.unidades_completo")
        );
        if (this.unidades_selecionadas_object.length == 0) {
          this.router.navigateByUrl("/configuracao");
        }
      }
    }, 1000);
  }

  isUnidadesCompleto(): boolean {
    const unidadesCompleto = localStorage.getItem("totem.unidades_completo");
    return (
      unidadesCompleto !== null &&
      unidadesCompleto !== "[]" &&
      unidadesCompleto !== ""
    );
  }

  ngOnInit() {
    const unidadesCompleto = JSON.parse(
      localStorage.getItem("totem.unidades_completo")
    );
    if (unidadesCompleto.length) {
      setTimeout(() => {
        this.router.navigateByUrl("/unidade");
      }, 3000);
    }
  }

  quantasUnidades(): number {
    var count = 0;
    this.unidades_selecionadas_object.forEach((e) => {
      count++;
    });
    return count;
  }

  go() {
    if (this.quantasUnidades() == 0) {
      window.alert(
        "Não há unidades selecionadas! Por favor, efetue essa configuração. Erro: O número de unidades em unidades_selecionas_object é 0."
      );
      this.router.navigateByUrl("/configuracao");
    } else {
      this.router.navigateByUrl("/unidade");
    }
  }
}
