import { Component, OnInit, OnDestroy } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';

@Component({
  selector: 'app-servico',
  templateUrl: './servico.component.html',
  styleUrls: ['./servico.component.css']
})
export class ServicoComponent implements OnInit, OnDestroy {

  servicos = [];
  private id;
  private timeout: any;

  constructor(private route: ActivatedRoute, private router: Router) {}

  ngOnInit() {
    this.id = +this.route.snapshot.paramMap.get('id');
    
    const chavesObrigatorias = [
      "totem.servicos",
      "totem.servicos_selecionados",
      "totem.unidades_completo",
      "totem.unidades_dados"
    ];

    const precisaLimparERedirecionar = chavesObrigatorias.some(key => {
      const dado = localStorage.getItem(key);
      
      if (!dado) return true;

      try {
        const parsed = JSON.parse(dado);
        return Array.isArray(parsed) && parsed.length === 0;
      } catch (e) {
        return true; 
      }
    });

    if (precisaLimparERedirecionar) {
      this.executarLimpezaGeral();
      return; 
    }

    this.servicos = JSON.parse(localStorage.getItem("totem.servicos_selecionados"));

    this.timeout = setTimeout(() => {
      localStorage.setItem("totem.timeout", "");
      this.router.navigateByUrl("/unidade");
    }, 30000);

    localStorage.setItem("totem.timeout", this.timeout.toString());
  }

  private executarLimpezaGeral() {
    const prefixosParaRemover = ['totem.servicos', 'totem.unidades'];

    Object.keys(localStorage)
      .filter(key => prefixosParaRemover.some(prefixo => key.startsWith(prefixo)))
      .forEach(key => localStorage.removeItem(key));

    this.router.navigateByUrl('/');
  }

  ngOnDestroy() {
    if (this.timeout) {
      clearTimeout(this.timeout);
    }
  }
}