import { Component, OnDestroy } from '@angular/core';
import { Router } from '@angular/router';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent implements OnDestroy {
  private clickTimes: number[] = [];
  showModal = false;
  enteredPassword = '';
  private modalTimeout: any;

  constructor(private router: Router) {}

  onLogoClick() {
    const now = Date.now();
    this.clickTimes.push(now);
    if (this.clickTimes.length > 10) this.clickTimes.shift();

    if (this.clickTimes.length === 10) {
      if (this.clickTimes[9] - this.clickTimes[0] <= 5000) {
        this.openModal();
        this.clickTimes = [];
      }
    }
  }

  openModal() {
    this.showModal = true;
    this.enteredPassword = '';
    this.resetTimer();
  }

  closeModal() {
    this.showModal = false;
    this.clearTimer();
  }

  addDigit(digit: string) {
    if (this.enteredPassword.length < 8) { // Limite DDMMYYYY
      this.enteredPassword += digit;
      this.resetTimer();
    }
  }

  clearDigits() {
    // Apaga o último dígito ou limpa tudo se preferir
    this.enteredPassword = this.enteredPassword.slice(0, -1);
    this.resetTimer();
  }

  confirm() {
    const correctPass = this.getCurrentDatePassword();
    if (this.enteredPassword === correctPass) {
      this.closeModal();
      this.router.navigate(['/configuracao']);
    } else {
      alert('Senha incorreta!');
      this.enteredPassword = '';
      this.resetTimer();
    }
  }

  cancel() {
    this.closeModal();
    this.router.navigate(['/']);
  }

  private resetTimer() {
    this.clearTimer();
    this.modalTimeout = setTimeout(() => this.closeModal(), 30000);
  }

  private clearTimer() {
    if (this.modalTimeout) clearTimeout(this.modalTimeout);
  }

  private getCurrentDatePassword(): string {
    const now = new Date();
    const day = String(now.getDate()).padStart(2, '0');
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const year = String(now.getFullYear());
    return `${day}${month}${year}`;
  }

  ngOnDestroy() {
    this.clearTimer();
  }
}